import sys
import csv
import json

def normalize_item(name: str) -> str:
    """Collapse whitespace to single spaces and casefold."""
    # Split on whitespace and join with single space, then casefold
    return ' '.join(name.split()).casefold()

def parse_quantity(q_str: str) -> int:
    """Parse quantity: blank means 1, otherwise nonnegative integer."""
    stripped = q_str.strip()
    if stripped == '':
        return 1
    return int(stripped)

def main():
    if len(sys.argv) < 2:
        return
    input_file = sys.argv[1]

    # Use csv.reader to parse the CSV
    with open(input_file, 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader, None)

        # Dictionary to accumulate quantities by normalized item name
        accum = {}

        for row in reader:
            if len(row) < 2:
                continue  # Skip malformed rows

            item_raw = row[0]
            qty_raw = row[1]

            normalized = normalize_item(item_raw)

            # Skip empty normalized names
            if normalized == '':
                continue

            quantity = parse_quantity(qty_raw)

            # Accumulate quantities
            if normalized in accum:
                accum[normalized] += quantity
            else:
                accum[normalized] = quantity

    # Build list of objects sorted by normalized item name
    result = [
        {"item": item, "quantity": qty}
        for item, qty in sorted(accum.items())
    ]

    # Output exactly one JSON value to stdout
    print(json.dumps(result))

if __name__ == '__main__':
    main()
